class Order {
  #status: "pending" | "paid" | "refunded" = "pending";
  get status() { return this.#status; }
  markPaid() {
    if (this.#status !== "pending") throw new Error(`cannot pay an order that is ${this.#status}`);
    this.#status = "paid";
  }
  markRefunded() {
    if (this.#status !== "paid") throw new Error(`cannot refund an order that is ${this.#status}`);
    this.#status = "refunded";
  }
}

const order = new Order();
for (const step of ["markPaid", "markRefunded", "markPaid"] as const) {
  try {
    order[step]();
    console.log(step, "->", order.status);
  } catch (error) {
    console.log((error as Error).message);
  }
}

function price(subtotalKobo: number, discountRate: number) {
  const afterDiscount = Math.round(subtotalKobo * (1 - discountRate));
  const vat = Math.round(afterDiscount * 0.075);
