type Transfer = { from: string; to: string; amountKobo: number };

function validateTransfer(t: Transfer): string[] {
  const problems: string[] = [];
  if (!Number.isInteger(t.amountKobo) || t.amountKobo <= 0) problems.push("amount must be positive whole kobo");
  if (t.from === t.to) problems.push("cannot transfer to the same account");
  if (!/^\d{10}$/.test(t.from) || !/^\d{10}$/.test(t.to)) problems.push("account number must be 10 digits");
  return problems;
}

console.log(validateTransfer({ from: "0123456789", to: "9876543210", amountKobo: 1000000 }));
console.log(validateTransfer({ from: "12345", to: "12345", amountKobo: 10.5 }).length);

