class Account {
  #balanceKobo = 0;

  get balanceKobo(): number {
    return this.#balanceKobo;
  }

  deposit(kobo: number): void {
    this.#balanceKobo += kobo;
  }

  withdraw(kobo: number): void {
    if (kobo > this.#balanceKobo) throw new Error("insufficient funds");
    this.#balanceKobo -= kobo;
  }
}

const account = new Account();
account.deposit(500000);
account.withdraw(200000);
console.log(account.balanceKobo);
try {
  account.withdraw(900000);
} catch (error) {
  console.log((error as Error).message);
}
