type Raw = { status: string; data: Record<string, string> };
type ChargeResult = { ok: true; chargeId: string } | { ok: false; reason: "declined" };

function toChargeResult(raw: Raw): ChargeResult {
  if (raw.status === "success" && raw.data["processor_response"] === "Approved") {
    return { ok: true, chargeId: raw.data["flw_ref"] ?? "" };
  }
  return { ok: false, reason: "declined" };
}

const a = toChargeResult({ status: "success", data: { processor_response: "Approved", flw_ref: "FLW-12" } });
const b = toChargeResult({ status: "success", data: { processor_response: "Insufficient funds", flw_ref: "FLW-13" } });
